// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        Forwarder f = new Forwarder();

        bool ok;
        if (uint160(caller) % 2 == 0) {
            vm.prank(caller);
            try c.proxiableUUID() returns (bytes32 slot) {
                bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
                ok = (slot == expected);
            } catch {
                ok = false;
            }
        } else {
            try f.callProxiable(address(c)) returns (bytes32 slot) {
                bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
                ok = (slot == expected);
            } catch {
                ok = false;
            }
        }

        assertTrue(ok);
    }
}

contract Forwarder {
    function callProxiable(address target) external returns (bytes32 slot) {
        (bool success, bytes memory ret) = target.call(abi.encodeWithSelector(bytes4(keccak256("proxiableUUID()"))));
        if (!success) revert();
        slot = abi.decode(ret, (bytes32));
    }
}
